<script setup lang="ts">import{computed,ref}from'vue';import{useRoute}from'vue-router';import AccountShell from'../components/AccountShell.vue';import{useAppStore}from'../stores/app';const route=useRoute(),store=useAppStore(),sent=ref(false),openFaq=ref(0);const key=computed(()=>String(route.params.page||route.path.slice(1)));const faqs=['OK Coin 是什么？','卡池概率如何计算？','为什么十连抽没有额外保底？','卡牌如何回收为 OK Coin？','实物发货需要满足什么条件？','购买后可以退款或重抽吗？'];const isAccount=computed(()=>key.value.startsWith('account/'))</script>
